-- Numbers written as text and text read as numbers: the coercion that
-- happens behind arithmetic and concatenation, 'tonumber' in every base
-- it accepts, and the integer/float distinction that 5.4 keeps visible
-- through 'math.type' and through what 'tostring' prints.
local function show(...)
  local n = select('#', ...)
  local t = {}
  for i = 1, n do
    local v = (select(i, ...))
    if type(v) == "string" then t[i] = string.format("%q", v)
    elseif v == nil then t[i] = "nil"
    elseif type(v) == "number" then t[i] = string.format("%.17g", v)
    else
      local ok, s = pcall(tostring, v)
      t[i] = ok and s or ("<" .. type(v) .. ">")
    end
  end
  return table.concat(t, "|")
end
local function rec(f, ...)
  local ok, e = pcall(f, ...)
  if ok then return "ok|" .. show(...) end
  return "err|" .. (tostring(e):gsub("^[^:]*:%d+: ", ""))
end
-- a value and whether it is an integer or a float
local function kind(v) return show(v) .. ":" .. (math.type(v) or type(v)) end

print("== arithmetic on strings ==")
print(kind("10" + 0))
print(kind("10.0" + 0))
print(kind("10.5" + 0))
print(kind("0x10" + 0))
print(kind("0X10" + 0))
print(kind("0x10p4" + 0))
print(kind("1e2" + 0))
print(kind("1E2" + 0))
print(kind(".5" + 0))
print(kind("5." + 0))
print(kind(" 10 " + 0))
print(kind("\t10\n" + 0))
print(kind("-10" + 0))
print(kind("+10" + 0))
print(kind("10 " + 0))
print(kind(" 10" + 0))
print(rec(function() return "abc" + 0 end))
print(rec(function() return "" + 0 end))
print(rec(function() return " " + 0 end))
print(rec(function() return "10a" + 0 end))
print(rec(function() return "1 0" + 0 end))
print(rec(function() return "0x" + 0 end))
print(rec(function() return "1e" + 0 end))
print(rec(function() return "1e+" + 0 end))
print(rec(function() return "--1" + 0 end))
print(rec(function() return "1,5" + 0 end))
print(rec(function() return "inf" + 0 end))
print(rec(function() return "nan" + 0 end))
print(rec(function() return "0x1p" + 0 end))
print(rec(function() return "0x.8p1" + 0 end))
print(rec(function() return "0x1.8p1" + 0 end))

print("== the same, through concatenation and comparison ==")
print(kind(10 .. ""))
print(kind(10.0 .. ""))
print(kind(0.5 .. ""))
print(kind(1 / 0 .. ""))
print(kind(0 / 0 .. ""))
print(kind(math.maxinteger .. ""))
print(kind(math.mininteger .. ""))
print(rec(function() return "10" < "9" end))
print(rec(function() return "10" < 9 end))
print(rec(function() return 10 .. nil end))
print(rec(function() return 10 .. {} end))
print(rec(function() return #10 end))
print(rec(function() return #"10" + 0 end))

print("== integer and float distinction ==")
print(math.type(1), math.type(1.0), math.type("1"), math.type("x"))
print(kind(1), kind(1.0), kind(3 / 1), kind(4 / 2), kind(7 // 2), kind(-7 // 2))
print(kind(2 ^ 31), kind(2 ^ 63), kind(2 ^ -1))
print(kind(1e15), kind(1e16), kind(math.maxinteger + 0.0))
print(kind(3 % 2), kind(3.0 % 2), kind(-3 % 2), kind(3 % -2))
print(kind(1 | 0), kind(1.0 | 0), kind(1.5 | 0))
print(math.tointeger(1.0), math.tointeger(1.5), math.tointeger(2 ^ 70))
print(math.tointeger("3"), math.tointeger("3.0"), math.tointeger("3.5"))
print(math.tointeger(math.maxinteger), math.tointeger(1 / 0), math.tointeger(0 / 0))
print(rec(math.tointeger))
print(rec(math.tointeger, nil))
print(rec(math.tointeger, true))
print(rec(math.tointeger, {}))
print(math.ult(1, 2), math.ult(2, 1), math.ult(-1, 1), math.ult(math.maxinteger, math.mininteger))
print(rec(math.ult, 1))
print(rec(math.ult, 1, 2, 3))
print(rec(math.ult, 1.5, 2))
print(rec(math.ult, "1", 2))
print(math.fmod(7, 3), math.fmod(-7, 3), math.fmod(7, -3), math.fmod(7.5, 2))
print(kind(math.fmod(7, 3)), kind(math.fmod(7.5, 2)))
print(rec(math.fmod, 1, 0))
print(rec(math.fmod, 1))
print(kind(math.abs(math.mininteger)))
print(kind(math.floor(-0.5)), kind(math.ceil(0.5)), kind(math.floor(2 ^ 70)))
print(rec(math.floor, "1"))
print(rec(math.floor))
print(rec(math.floor, 1, 2))
print(rec(math.ceil, 0 / 0))
print(math.max(1, 2), math.min(1, 2), math.max(1), math.max())
print(rec(math.max, "a"))
print(rec(math.max, 1, "a"))

print("== tonumber in every base ==")
for b = 2, 36 do
  print(b, rec(tonumber, "z", b))       -- the largest digit of each base
end
print(rec(tonumber, "10", 2), rec(tonumber, "ff", 16), rec(tonumber, "FF", 16))
print(rec(tonumber, "10", 37))
print(rec(tonumber, "10", 1))
print(rec(tonumber, "10", 0))
print(rec(tonumber, "10", -1))
print(rec(tonumber, "10", 1.0))
print(rec(tonumber, "10", 1.5))
print(rec(tonumber, "10", "16"))
print(rec(tonumber, " 10 ", 16))
print(rec(tonumber, "-ff", 16), rec(tonumber, "+ff", 16))
print(rec(tonumber, "", 16))
print(rec(tonumber, "0x10", 16))
print(rec(tonumber, "ffffffffffffffffff", 16))
print(rec(tonumber, "7fffffffffffffff", 16))
print(rec(tonumber, "8000000000000000", 16))
print(rec(tonumber, "1", 10))
print(rec(tonumber, "1.5", 10))
print(rec(tonumber, "1.5"))
print(rec(tonumber, "  1.5  "))
print(rec(tonumber, nil))
print(rec(tonumber))
print(rec(tonumber, 10))
print(rec(tonumber, 10, 10))
print(rec(tonumber, true))
print(rec(tonumber, {}))

print("== what the lexer makes of a literal ==")
local function lit(s)
  local f = load("return " .. s)
  if not f then return "E" end
  return kind(f())
end
print(lit("1"), lit("1.0"), lit("1e2"), lit("0x10"), lit("0x10.8"))
print(lit("0x1p4"), lit("0x.8p4"), lit("1e400"), lit("-1e400"))
print(lit("1e-400"), lit("0x7fffffffffffffff"), lit("0x8000000000000000"))
print(lit("0xffffffffffffffff"), lit("0x1p1000"), lit("0x1p-1000"))
print(lit("9223372036854775807"), lit("9223372036854775808"))
print(lit("-9223372036854775808"), lit("-9223372036854775809"))
print(lit("3"), lit("3."), lit(".3"), lit("3.e2"), lit("3e"), lit("0xap1"))
print(lit("1e308"), lit("1e309"), lit("5e-324"), lit("1e-323"))
print("done")
